public boolean validateUnitOfMeasure()
{
    boolean ret = next validateUnitOfMeasure();

    // Clear error message when the discount line is creating. Need to open the Edit price attribute form.
    if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()) &&
        !ret &&
        !this.PriceAttributeGroupCombinationRecId)
    {
        infolog.clear(infolog.line() - 1);
        return true;
    }

    return ret;
}

public void delete()
{
    ttsbegin;

    if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()) &&
        this.LinePricingRule)
    {
        GUPPricingRule::find(this.LinePricingRule, true).delete();
    }

    next delete();

    ttscommit;
}

public void setPricingRuleReference(FieldId _pricingRuleFieldId, RefRecId _pricingRuleRecID)
{
    ttsbegin;

    this.selectForUpdate(true);
    this.(_pricingRuleFieldId) = _pricingRuleRecID;

    this.update();

    ttscommit;
}

public display GUPPriceAttributeGroupPriority displayCombinationPriceAttributeGroupPriority()
{
    GUPPriceComponentCodePriceAttributeGroupCombination priceAttributeGroupCombination;

    select firstonly Priority from priceAttributeGroupCombination
        where priceAttributeGroupCombination.RecId == this.PriceAttributeGroupCombinationRecId;

    return priceAttributeGroupCombination.Priority;
}

    public void copyRetailPeriodicThresholdDiscountlines(boolean copyLinesUnderSameHeader,  RetailPeriodicDiscountLine _periodicDiscountLine,
														Num newOfferId = '')
    {
        RetailDiscountLineThresholdApplying	retailDiscountLineThresholdApplyingNew;
        Num offerId = copyLinesUnderSameHeader ? this.OfferId : newOfferId;
        LineNum lineNum = copyLinesUnderSameHeader ? RetailPeriodicDiscountLine::lastLineNum(this.OfferId) + 1 : this.LineNum;

		_periodicDiscountLine.LineNum				= lineNum;
        _periodicDiscountLine.OfferId				= offerId;
        _periodicDiscountLine.LinePricingRule		= GUPPricingRule::find(this.LinePricingRule).copy().RecId;
        _periodicDiscountLine.RetailGroupMemberLine	= RetailGroupMemberLine::createRetailGroupMemberV2();
        _periodicDiscountLine.insert();
    }

    public void copyRetailPeriodicDiscountLine(boolean copyLinesUnderSameHeader, Num newOfferId = '')
    {
        RetailPeriodicDiscountLine periodicDiscountLine;
        Num offerId = copyLinesUnderSameHeader ? this.OfferId : newOfferId;
        LineNum lineNum = copyLinesUnderSameHeader ? RetailPeriodicDiscountLine::lastLineNum(this.OfferId) + 1 : this.LineNum;

        if (this is RetailDiscountLineOffer)
        {
            RetailDiscountLineOffer retailDiscountOfferLineNew;

            retailDiscountOfferLineNew.data(this);
            retailDiscountOfferLineNew.initValue();
            periodicDiscountLine = retailDiscountOfferLineNew;
        }
        else if (this is RetailDiscountLineMultibuy)
        {
            RetailDiscountLineMultibuy discountLineMultibuyNew;

            discountLineMultibuyNew.data(this);
            discountLineMultibuyNew.initValue();
            periodicDiscountLine = discountLineMultibuyNew;
        }
        else if (this is RetailDiscountLineMixAndMatch)
        {
            RetailDiscountLineMixAndMatch discountLineMixAndMatchNew;
            discountLineMixAndMatchNew.data(this);
            discountLineMixAndMatchNew.initValue();
            periodicDiscountLine = discountLineMixAndMatchNew;
        }

        else if (this is GUPFreeItemDiscountLine)
        {
            GUPFreeItemDiscountLine	freeItemDiscountLine, freeItemDiscountLineNew;
            GUPFreeItemLine	freeItemLine, freeItemLineNew, freeItemLineExists;

            freeItemDiscountLineNew.data(this);
            freeItemDiscountLineNew.initValue();
            freeItemDiscountLineNew.FreeItemGroup = freeItemDiscountLineNew.FreeItemGroup;
            periodicDiscountLine = freeItemDiscountLineNew;

            select freeItemDiscountLine where freeItemDiscountLine.OfferId == this.OfferId
                && freeItemDiscountLine.RecId ==  this.RecId;

            select freeItemLineExists where freeItemLineExists.FreeItemGroup == freeItemDiscountLineNew.FreeItemGroup
                && freeItemLineExists.FreeItemId == offerId;

            if (!freeItemLineExists)
            {
				while select freeItemLine where freeItemLine.FreeItemGroup == freeItemDiscountLine.FreeItemGroup
					&& freeItemLine.FreeItemId == freeItemDiscountLine.OfferId
				{
					freeItemLineNew.initValue();
					freeItemLineNew.FreeItemId				= offerId;
                    freeItemLineNew.FreeItemGroup			= freeItemLine.FreeItemGroup;
					freeItemLineNew.Product					= freeItemLine.Product;
					freeItemLineNew.UnitOfMeasure			= freeItemLine.UnitOfMeasure;
					freeItemLineNew.InventDimId				= freeItemLine.InventDimId;
					freeItemLineNew.FreeItemLineQtyFactor	= freeItemLine.FreeItemLineQtyFactor;
					freeItemLineNew.Variant					= freeItemLine.Variant;
					freeItemLineNew.insert();
				}
            }
        }
        periodicDiscountLine.LineNum				= lineNum;
        periodicDiscountLine.OfferId				= offerId;
        periodicDiscountLine.LinePricingRule		= GUPPricingRule::find(this.LinePricingRule).copy().RecId;
        periodicDiscountLine.RetailGroupMemberLine	= RetailGroupMemberLine::createRetailGroupMemberV2();
        periodicDiscountLine.insert();
    }
